    const form = document.getElementById('support-form');
    const nameInput = document.getElementById('full-name');
    const emailInput = document.getElementById('email');
    const phoneInput = document.getElementById('phone');
    const statusMessage = document.getElementById('form-status');

    // Helper to display error
    const showError = (inputElement, errorId, message) => {
        const errorElement = document.getElementById(errorId);
        errorElement.textContent = message;
        errorElement.hidden = false;
        inputElement.setAttribute('aria-invalid', 'true');
    };

    // Helper to clear error
    const clearError = (inputElement, errorId) => {
        const errorElement = document.getElementById(errorId);
        errorElement.textContent = '';
        errorElement.hidden = true;
        inputElement.removeAttribute('aria-invalid');
    };

    // Email regex for basic validation
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

    // Basic phone regex (allows digits, spaces, hyphens, plus, parens)
    const phoneRegex = /^[\d\s\-\+\(\)]+$/;

    form.addEventListener('submit', (e) => {
        e.preventDefault();

        let isValid = true;
        let firstInvalidElement = null;

        // Clear previous status
        statusMessage.hidden = true;
        statusMessage.className = 'status-message';
        statusMessage.textContent = '';

        // Validate Full Name
        if (!nameInput.value.trim()) {
            showError(nameInput, 'name-error', 'Full name is required.');
            isValid = false;
            if (!firstInvalidElement) firstInvalidElement = nameInput;
        } else {
            clearError(nameInput, 'name-error');
        }

        // Validate Email
        if (!emailInput.value.trim()) {
            showError(emailInput, 'email-error', 'Email address is required.');
            isValid = false;
            if (!firstInvalidElement) firstInvalidElement = emailInput;
        } else if (!emailRegex.test(emailInput.value.trim())) {
            showError(emailInput, 'email-error', 'Please enter a valid email address.');
            isValid = false;
            if (!firstInvalidElement) firstInvalidElement = emailInput;
        } else {
            clearError(emailInput, 'email-error');
        }

        // Validate Phone (Optional, but if provided should be validish)
        if (phoneInput.value.trim() && !phoneRegex.test(phoneInput.value.trim())) {
            showError(phoneInput, 'phone-error', 'Please enter a valid phone number (e.g., +1 (555) 123-4567).');
            isValid = false;
            if (!firstInvalidElement) firstInvalidElement = phoneInput;
        } else {
            clearError(phoneInput, 'phone-error');
        }

        // Handle submission result
        if (!isValid) {
            // Move focus to the first invalid field for screen reader users and keyboard users
            firstInvalidElement.focus();
        } else {
            // Simulate successful form submission
            form.reset();

            // Announce success
            statusMessage.textContent = 'Your request has been successfully submitted. We will contact you soon.';
            statusMessage.classList.add('success');
            statusMessage.hidden = false;

            // Clear any lingering focus to emphasize status message context
            document.activeElement.blur();
        }
    });

    // Optional enhancements: clear error on input (once the user starts fixing it)
    [nameInput, emailInput, phoneInput].forEach(input => {
        input.addEventListener('input', () => {
            if (input.hasAttribute('aria-invalid')) {
                const errorId = input.getAttribute('aria-describedby').split(' ').find(id => id.includes('error'));
                if (errorId) clearError(input, errorId);
            }
        });
    });
});

